-- Test real RPC bodies against session-local data; no real accounts or matches change.
BEGIN;
CREATE TEMP TABLE profiles (LIKE public.profiles INCLUDING ALL);
CREATE TEMP TABLE matches (LIKE public.matches INCLUDING ALL);
CREATE TEMP TABLE match_players (LIKE public.match_players INCLUDING ALL);
CREATE TEMP TABLE queue (LIKE public.queue INCLUDING ALL);
CREATE TEMP TABLE match_kick_votes (LIKE public.match_kick_votes INCLUDING ALL);
CREATE TEMP TABLE match_kick_ballots (LIKE public.match_kick_ballots INCLUDING ALL);
CREATE TEMP TABLE match_replacements (LIKE public.match_replacements INCLUDING ALL);
CREATE TEMP TABLE mod_actions (LIKE public.mod_actions INCLUDING ALL);
CREATE FUNCTION pg_temp.has_role(u uuid, r public.app_role) RETURNS boolean LANGUAGE sql AS $$ SELECT coalesce(u::text=current_setting('test.admin',true),false) AND r='admin' $$;
DO $$ DECLARE n text; d text; t text; f text; BEGIN
 FOREACH n IN ARRAY ARRAY['kick_match_paused','backfill_match_gk','resolve_match_kick_gk','start_match_kick_gk','cast_match_kick_gk','admin_decide_match_kick_gk'] LOOP
  SELECT pg_get_functiondef(oid) INTO d FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=n;
  d:=replace(d,'FUNCTION public.'||n||'(','FUNCTION pg_temp.'||n||'(');
  d:=replace(d,'SET search_path TO ''public''','SET search_path TO pg_temp,public');
  FOREACH t IN ARRAY ARRAY['profiles','matches','match_players','queue','match_kick_votes','match_kick_ballots','match_replacements','mod_actions'] LOOP d:=replace(d,'public.'||t,t); END LOOP;
  FOREACH f IN ARRAY ARRAY['kick_match_paused','backfill_match_gk','resolve_match_kick_gk'] LOOP d:=replace(d,'public.'||f||'(','pg_temp.'||f||'('); END LOOP;
  d:=replace(d,'public.has_role(','pg_temp.has_role('); d:=replace(d,'auth.uid()','nullif(current_setting(''request.jwt.claim.sub'',true),'''')::uuid'); EXECUTE d;
 END LOOP;
END $$;
DO $$
DECLARE admin_id uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); target uuid:=gen_random_uuid(); voter uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); first_player uuid:=gen_random_uuid(); second_player uuid:=gen_random_uuid(); official uuid:=gen_random_uuid(); v uuid; blocked boolean:=false; before_deadline timestamptz;
BEGIN
 INSERT INTO profiles(id,name,rating) VALUES(actor,'Actor',100),(target,'Target',200),(voter,'Voter',100),(outsider,'Outsider',100),(first_player,'FIFO first',300),(second_player,'FIFO second',400),(official,'Official queue',400);
 INSERT INTO matches(id,mode,region,status,deadline,captain_a,captain_b) VALUES(m,5,'TESTE','draft',now()+interval '30 seconds',target,voter);
 INSERT INTO match_players(match_id,user_id,team,position,rating_before) VALUES(m,actor,'a','Ala',100),(m,target,'a','Goleiro',200),(m,voter,'b','Pivô',100);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 BEGIN PERFORM pg_temp.start_match_kick_gk(m,actor); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'self targeting allowed'; END IF;
 v:=pg_temp.start_match_kick_gk(m,target);
 IF (SELECT extract(epoch FROM ends_at-started_at) FROM match_kick_votes WHERE id=v)<>20 THEN RAISE EXCEPTION 'timer must be 20 seconds'; END IF;
 PERFORM pg_temp.cast_match_kick_gk(v,true);
 PERFORM set_config('request.jwt.claim.sub',target::text,true); blocked:=false;
 BEGIN PERFORM pg_temp.cast_match_kick_gk(v,true); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'target could vote'; END IF;
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true); blocked:=false;
 BEGIN PERFORM pg_temp.cast_match_kick_gk(v,true); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'outsider could vote'; END IF;
 PERFORM set_config('request.jwt.claim.sub',voter::text,true); PERFORM pg_temp.cast_match_kick_gk(v,false);
 UPDATE match_kick_votes SET ends_at=now()-interval '1 second' WHERE id=v;
 PERFORM pg_temp.resolve_match_kick_gk(m);
 IF NOT EXISTS(SELECT 1 FROM match_players WHERE match_id=m AND user_id=target) OR (SELECT status FROM match_kick_votes WHERE id=v)<>'rejected' THEN RAISE EXCEPTION 'tie must retain player'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true); v:=pg_temp.start_match_kick_gk(m,target); PERFORM pg_temp.cast_match_kick_gk(v,true);
 UPDATE match_kick_votes SET ends_at=now()-interval '1 second' WHERE id=v; PERFORM pg_temp.resolve_match_kick_gk(m);
 IF NOT EXISTS(SELECT 1 FROM match_players WHERE match_id=m AND user_id=target) OR (SELECT status FROM match_kick_votes WHERE id=v)<>'pending_admin' THEN RAISE EXCEPTION 'majority must wait for admin before removal'; END IF;
 IF NOT pg_temp.kick_match_paused(m) THEN RAISE EXCEPTION 'match must stay paused while admin decides'; END IF;
 blocked:=false; BEGIN PERFORM pg_temp.start_match_kick_gk(m,voter); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'new vote allowed while admin decision pending'; END IF;
 blocked:=false; BEGIN PERFORM pg_temp.admin_decide_match_kick_gk(v,true); EXCEPTION WHEN OTHERS THEN blocked:=true; END;
 IF NOT blocked THEN RAISE EXCEPTION 'non-admin approved expulsion'; END IF;
 PERFORM set_config('test.admin',admin_id::text,true); PERFORM set_config('request.jwt.claim.sub',admin_id::text,true);
 PERFORM pg_temp.admin_decide_match_kick_gk(v,false);
 IF NOT EXISTS(SELECT 1 FROM match_players WHERE match_id=m AND user_id=target) OR (SELECT status FROM match_kick_votes WHERE id=v)<>'rejected' THEN RAISE EXCEPTION 'admin rejection must keep player'; END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true); v:=pg_temp.start_match_kick_gk(m,target); PERFORM pg_temp.cast_match_kick_gk(v,true);
 UPDATE match_kick_votes SET ends_at=now()-interval '1 second' WHERE id=v; PERFORM pg_temp.resolve_match_kick_gk(m);
 PERFORM set_config('request.jwt.claim.sub',admin_id::text,true); PERFORM pg_temp.admin_decide_match_kick_gk(v,true);
 IF EXISTS(SELECT 1 FROM match_players WHERE match_id=m AND user_id=target) OR (SELECT status FROM match_kick_votes WHERE id=v)<>'approved' THEN RAISE EXCEPTION 'admin approval must expel'; END IF;
 IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=target) THEN RAISE EXCEPTION 'real account must survive'; END IF;
 IF NOT EXISTS(SELECT 1 FROM match_replacements WHERE match_id=m AND removed_id=target AND replacement_id IS NULL) THEN RAISE EXCEPTION 'empty queue must wait'; END IF;
 INSERT INTO queue(user_id,mode,region,position,joined_at) VALUES(official,5,'SA','Goleiro',now()-interval '10 minutes'),(first_player,5,'TESTE','Ala',now()-interval '2 minutes'),(second_player,5,'TESTE','Goleiro',now()-interval '1 minute');
 PERFORM pg_temp.backfill_match_gk(m);
 IF NOT EXISTS(SELECT 1 FROM match_players WHERE match_id=m AND user_id=first_player AND team='a') THEN RAISE EXCEPTION 'first waiting player regardless of position must replace'; END IF;
 IF NOT EXISTS(SELECT 1 FROM queue WHERE user_id=official) OR NOT EXISTS(SELECT 1 FROM queue WHERE user_id=second_player) THEN RAISE EXCEPTION 'pool isolation / FIFO violated'; END IF;
 IF (SELECT captain_a FROM matches WHERE id=m)<>first_player THEN RAISE EXCEPTION 'captain slot must transfer'; END IF;
 SELECT deadline INTO before_deadline FROM matches WHERE id=m; PERFORM pg_temp.backfill_match_gk(m);
 IF (SELECT deadline FROM matches WHERE id=m)<>before_deadline THEN RAISE EXCEPTION 'poll must not reset draft timer'; END IF;
END $$;
ROLLBACK;